import countriesJson from "./countries.json"
import saRegionsJson from "./sa-regions.json"

/**
 * Country / region / city reference data, bundled rather than fetched.
 *
 * A country picker has to render on first paint, work with no network, and
 * still be there when a free public API stops answering — so none of this is
 * a runtime call. Two sources, trimmed to the columns below:
 *
 * - `countries.json` — `dr5hn/countries-states-cities-database` (250 rows),
 *   the only one of the free datasets carrying an Arabic name per country.
 * - `sa-regions.json` / `sa-cities.json` / `sa-districts.json` — the MOMRAH
 *   Unified Municipal Coding (13 regions, 15,513 cities, 21,235 districts),
 *   generated by `back-end/scripts/generate-geo.cjs`. The English name is the
 *   stored value, so the generator pins it per id and never renames one that
 *   shipped — see the README.
 *
 * Only Saudi Arabia gets structured region/city pickers. Every other country
 * keeps free-text city and state inputs — inventing a half-covered dropdown
 * for 249 countries is worse than a text field the vendor can actually fill.
 */

/** One country, trimmed from the dr5hn dump. */
export interface Country {
  /** ISO 3166-1 alpha-2 — what `ShopLocation.country` stores. */
  code: string
  en: string
  ar: string
  /** Flag emoji; `""` where the source had none. */
  flag: string
  /** Calling code, no leading `+`. */
  dial: string
  /** ISO 4217. */
  currency: string
  /**
   * Postal-code pattern, where the country has one (189 of 250 do). Kept as a
   * source string rather than a `RegExp` so the table stays JSON. The dataset is
   * PCRE, so patterns a JS `RegExp` cannot parse were dropped when the file was
   * generated instead of being left to throw at the call site.
   */
  postal?: string
  /** Human hint for the shape, e.g. `#####`. Shown when a code does not match. */
  postalFormat?: string
}

/** A bilingual lookup row (Saudi region, or city). */
export interface GeoEntry {
  id: number
  en: string
  ar: string
}

export interface SaCity extends GeoEntry {
  /** The `SA_REGIONS[].id` this city sits in. */
  region: number
}

export interface SaDistrict extends GeoEntry {
  /** The `sa-cities.json` id this district sits in. */
  city: number
  /** The `SA_REGIONS[].id` this district sits in. */
  region: number
}

export const COUNTRIES = countriesJson as Country[]
export const SA_REGIONS = saRegionsJson as GeoEntry[]

/** The one country with structured region/city data behind it. */
export const SA_COUNTRY_CODE = "SA"

const BY_CODE = new Map(COUNTRIES.map((c) => [c.code, c]))

export function countryByCode(code?: string | null): Country | undefined {
  if (!code) return undefined
  return BY_CODE.get(code.trim().toUpperCase())
}

/**
 * Resolve whatever is actually sitting in `ShopLocation.country`.
 *
 * The field is a free `String` and was filled by a plain text input until this
 * pane grew a picker, so existing shops hold a display name ("Saudi Arabia",
 * "المملكة العربية السعودية") rather than an ISO2 code. Falling back to a name
 * match means those rows light up in the picker and normalise to a code the
 * next time the vendor saves, instead of reading as "no country set".
 */
export function resolveCountry(value?: string | null): Country | undefined {
  const raw = value?.trim()
  if (!raw) return undefined
  const byCode = BY_CODE.get(raw.toUpperCase())
  if (byCode) return byCode
  const folded = foldSearch(raw)
  return COUNTRIES.find(
    (c) => foldSearch(c.en) === folded || foldSearch(c.ar) === folded,
  )
}

/**
 * Compiled postal patterns, cached — a `RegExp` per country built once instead
 * of on every keystroke in the address dialog.
 */
const POSTAL_CACHE = new Map<string, RegExp | null>()

function postalPattern(country: Country): RegExp | null {
  if (!country.postal) return null
  const hit = POSTAL_CACHE.get(country.code)
  if (hit !== undefined) return hit
  let compiled: RegExp | null = null
  try {
    compiled = new RegExp(country.postal)
  } catch {
    // Generation already dropped the PCRE-only patterns; this is the belt for
    // a hand-edited table. A pattern we cannot compile must not block a save.
    compiled = null
  }
  POSTAL_CACHE.set(country.code, compiled)
  return compiled
}

/**
 * Does this postal code fit the country's shape?
 *
 * Deliberately permissive at both ends: an empty code is fine (the field is
 * optional), and a country the dataset has no pattern for always passes. This
 * is a nudge on a form, not a gate — 61 countries have no pattern at all, and
 * refusing an address because our table is thin would be worse than a wrong
 * postal code.
 */
export function isValidPostalCode(
  countryCode: string | null | undefined,
  zip: string,
): boolean {
  const value = zip.trim()
  if (!value) return true
  const country = resolveCountry(countryCode)
  if (!country) return true
  const pattern = postalPattern(country)
  if (!pattern) return true
  return pattern.test(value)
}

/**
 * Arabic names that replace `countries.json`'s at display time. Its `ar` column
 * is the source dataset's translation, and a handful of rows are machine-
 * translation errors that read as nonsense to an Arabic merchant: Turkey as
 * «ديك رومى» (the bird), Réunion as «جمع شمل» (a gathering), the Isle of Man as
 * «رجل (جزيرة)», Heard Island as «سمعت جزيرة», Cameroon left in English. They
 * are fixed here rather than in the JSON so a regenerated table cannot bring
 * them back; spelling variants («الجابون» / «الغابون») are left alone.
 *
 * PS: the source row says «احتلت الأراضي الفلسطينية»; this shows
 * «فلسطين», matching the customer, coupon, shipping and signup pickers.
 */
const AR_NAME_OVERRIDES: Readonly<Record<string, string>> = {
  PS: "فلسطين",
  TR: "تركيا",
  RE: "روينيون",
  IM: "جزيرة مان",
  TL: "تيمور الشرقية",
  HM: "جزيرة هيرد وجزر ماكدونالد",
  CM: "الكاميرون",
  PH: "الفلبين",
  CK: "جزر كوك",
  HK: "هونغ كونغ",
  MO: "ماكاو",
  PM: "سان بيير وميكلون",
  VC: "سانت فنسنت وجزر غرينادين",
  GS: "جورجيا الجنوبية وجزر ساندويتش الجنوبية",
  UM: "جزر الولايات المتحدة النائية",
}

/** Localized name, falling back to English for any locale we have no column for. */
export function geoLabel(
  entry: Pick<GeoEntry, "en" | "ar"> & { code?: string },
  locale: string,
) {
  if (!locale.startsWith("ar")) return entry.en
  return (entry.code && AR_NAME_OVERRIDES[entry.code]) || entry.ar
}

/**
 * The Saudi city table is ~1MB — a lazy chunk, not part of the settings
 * bundle, because nothing needs it until the address dialog is opened on a
 * Saudi shop. The promise is cached, so reopening the dialog is instant and
 * two pickers mounted together share one fetch.
 */
let citiesPromise: Promise<SaCity[]> | null = null

export function loadSaCities(): Promise<SaCity[]> {
  if (!citiesPromise) {
    citiesPromise = import("./sa-cities.json").then(
      (m) => m.default as unknown as SaCity[],
    )
  }
  return citiesPromise
}

/** The district table, ~1.6MB, loaded the same way and only by its picker. */
let districtsPromise: Promise<SaDistrict[]> | null = null

export function loadSaDistricts(): Promise<SaDistrict[]> {
  if (!districtsPromise) {
    districtsPromise = import("./sa-districts.json").then(
      (m) => m.default as unknown as SaDistrict[],
    )
  }
  return districtsPromise
}

/**
 * Fold a query and a candidate onto common ground before comparing.
 *
 * Arabic place names are written several ways that all have to match one
 * search: the alef carries a hamza or does not (أبها / ابها), the final ya and
 * alef-maqsura are interchangeable (نعمي / نعمى), ta-marbuta is often typed as
 * a plain ha (مكة / مكه), and tashkeel may or may not be there. Latin names in
 * the same table carry diacritics from the transliteration (`Ţubarjal`,
 * `Al-'Ula`), which `NFD` + combining-mark strip flattens the same way.
 */
export function foldSearch(value: string) {
  return value
    .normalize("NFD")
    .replace(/[\u0300-\u036f\u0610-\u061a\u064b-\u065f\u0670]/g, "")
    .replace(/[أإآٱ]/g, "ا")
    .replace(/ى/g, "ي")
    .replace(/ة/g, "ه")
    .replace(/[\s'’ʻ`\-_.,()]+/g, "")
    .toLowerCase()
}
